# Kaggle driver: B-form floor finite facts (spanlemma.py, bicliques.py). Code embedded.
import os, sys, time, subprocess
print('START driver', time.strftime('%H:%M:%S'), flush=True)
os.chdir('/kaggle/working')
FILES = {'spanlemma.py': '"""Finite facts for the B-form floor (BFORM2.md), exact integer arithmetic, characteristic 0.  Apache-2.0.\nS0  label caps: max ports in a d-dim subspace of F_2^9 is f(7) = 36, f(8) = 60.\nS1  hyperplanes holding >= 38 E8 lines are exactly the E7 hyperplanes (normal = root, 63 lines) and the D7\n    hyperplanes (normal = norm-4 vector, 42 lines); every other hyperplane holds <= 37 lines (E6+A1), by the\n    classification of E8 hyperplane flats (maximal parabolics).  Checked here: the E7/D7 hyperplanes hold\n    <= 55 ports, so |N(y)| >= 49 for every real y != 0.\nS2  Span lemma: for every label z != 0 (O(z) = ports with label.z = 1, |O(z)| >= 44) and every E7/D7\n    hyperplane H, the number of ports of O(z) outside H is 0 or >= 5.\nS3  biclique: if A x B is pairwise non-orthogonal and |A| >= 13 then |B| <= 4 (bicliques.py)."""\nimport itertools, time\nT0 = time.time()\ndef log(*a): print(\'[%7.1fs]\' % (time.time() - T0), *a, flush=True)\nlog(\'START spanlemma\')\nP = [11, 19, 35, 131, 259, 13, 21, 37, 69, 133, 261, 41, 73, 265, 49, 81, 145, 273, 161, 193, 321, 385, 14, 22, 38, 70, 134, 262, 26, 74, 138, 50, 146, 274, 98, 290, 194, 322, 386, 28, 44, 140, 268, 84, 148, 276, 100, 164, 292, 196, 324, 388, 56, 88, 152, 280, 168, 296, 200, 328, 392, 112, 176, 304, 208, 336, 400, 224, 352, 416, 508, 506, 502, 494, 478, 446, 382, 254, 505, 501, 493, 477, 445, 381, 253, 499, 475, 443, 379, 251, 487, 471, 439, 375, 247, 463, 431, 367, 239, 415, 351, 223, 319, 191]\nLINES = [q for q in range(512) if bin(q).count(\'1\') in (3, 7)]\ndef root(q):  # 3 x root, A8 coordinates\n    c = [(q >> k) & 1 for k in range(9)]\n    if sum(c) == 7:\n        i, j = [k for k in range(9) if not c[k]]; r = [0] * 9; r[i] = 3; r[j] = -3; return tuple(r)\n    return tuple(2 if c[k] else -1 for k in range(9))\nRT = {q: root(q) for q in LINES}\ndef dot(a, b): return sum(x * y for x, y in zip(a, b))\nassert all(dot(RT[q], RT[q]) == 18 for q in LINES)\n# S0\ndef span(vs):\n    s = {0}\n    for v in vs:\n        if v not in s: s |= {x ^ v for x in s}\n    return s\ndef ldot(a, b): return bin(a & b).count(\'1\') & 1\nf = {}\nfor d in (7, 8):\n    best = 0\n    # subspaces of dim d = z-perp intersections: dim 8 = z^perp, dim 7 = <z1,z2>^perp\n    if d == 8:\n        for z in range(1, 512): best = max(best, sum(1 for q in P if ldot(q, z) == 0))\n    else:\n        for z1 in range(1, 512):\n            for z2 in range(z1 + 1, 512):\n                best = max(best, sum(1 for q in P if ldot(q, z1) == 0 and ldot(q, z2) == 0))\n    f[d] = best\nlog(\'S0 label caps f(7), f(8) =\', f[7], f[8]); assert f[7] == 36 and f[8] == 60\n# S1 normals\nE7n = [RT[q] for q in LINES]\nD7 = set()\nfor a, b in itertools.combinations(LINES, 2):\n    if dot(RT[a], RT[b]) == 0:\n        for s in (1, -1):\n            v = tuple(x + s * y for x, y in zip(RT[a], RT[b]))\n            if v < tuple(-x for x in v): v = tuple(-x for x in v)\n            D7.add(v)\nD7n = sorted(D7)\nlog(\'E7 normals\', len(E7n), \'D7 normals\', len(D7n)); assert len(E7n) == 120 and len(D7n) == 1080\nassert all(dot(v, v) == 36 for v in D7n)\ninH = lambda n, q: dot(n, RT[q]) == 0\nlines7 = Counter = None\nc7 = {sum(1 for q in LINES if inH(n, q)) for n in E7n}; cd7 = {sum(1 for q in LINES if inH(n, q)) for n in D7n}\nlog(\'E8 lines per E7 hyperplane\', c7, \'per D7 hyperplane\', cd7); assert c7 == {63} and cd7 == {42}\nmp = max(sum(1 for q in P if inH(n, q)) for n in E7n + D7n)\nlog(\'S1 max ports in an E7/D7 hyperplane\', mp, \'-> min |N(y)| =\', 104 - mp); assert mp == 55\n# S2\nbad = []; hist = {}\nHP = [frozenset(q for q in P if inH(n, q)) for n in E7n + D7n]\nfor z in range(1, 512):\n    O = [q for q in P if ldot(q, z) == 1]\n    assert len(O) >= 44\n    for H in HP:\n        k = sum(1 for q in O if q not in H)\n        hist[k] = hist.get(k, 0) + 1 if k <= 8 else hist.get(k, 0)\n        if 1 <= k <= 4: bad.append((z, k))\nlog(\'S2 histogram of |O(z) \\\\ H| for small values (0..8):\', {k: v for k, v in sorted(hist.items()) if k <= 8})\nlog(\'S2 violations (1 <= |O(z) \\\\ H| <= 4):\', len(bad), bad[:10])\nlog(\'PASS\' if not bad else \'FAIL\')\nlog(\'DONE\')\n', 'bicliques.py': '"""B-form support structure on P104: A x B must be pairwise non-orthogonal (c_u beta_s = 0 on orthogonal pairs).\nEnumerate the closed bicliques (A = C(B), B = C(A), C(S) = lines non-orthogonal to every line of S, a line counts as\nnon-orthogonal to itself) with |A| >= 13, and the facts used in BFORM2.md.  Exact, char 0.\nApache-2.0."""\nimport itertools, time, json\nfrom fractions import Fraction as Q\nT0 = time.time()\ndef log(*a): print(\'[%7.1fs]\' % (time.time() - T0), *a, flush=True)\nlog(\'START bicliques\')\nP = [11, 19, 35, 131, 259, 13, 21, 37, 69, 133, 261, 41, 73, 265, 49, 81, 145, 273, 161, 193, 321, 385, 14, 22, 38, 70, 134, 262, 26, 74, 138, 50, 146, 274, 98, 290, 194, 322, 386, 28, 44, 140, 268, 84, 148, 276, 100, 164, 292, 196, 324, 388, 56, 88, 152, 280, 168, 296, 200, 328, 392, 112, 176, 304, 208, 336, 400, 224, 352, 416, 508, 506, 502, 494, 478, 446, 382, 254, 505, 501, 493, 477, 445, 381, 253, 499, 475, 443, 379, 251, 487, 471, 439, 375, 247, 463, 431, 367, 239, 415, 351, 223, 319, 191]\nN = len(P)\ndef root(q):\n    c = [(q >> k) & 1 for k in range(9)]\n    if sum(c) == 7:\n        i, j = [k for k in range(9) if not c[k]]; r = [0] * 9; r[i] = 3; r[j] = -3; return r\n    return [2 if c[k] else -1 for k in range(9)]\nR = [root(q) for q in P]\ndef ip(i, j): return sum(a * b for a, b in zip(R[i], R[j]))\nNB = [sum(1 << j for j in range(N) if ip(i, j) != 0) for i in range(N)]   # closed non-orth neighbourhood (incl. i)\nALL = (1 << N) - 1\ndef C(mask):\n    m = ALL\n    for i in range(N):\n        if mask >> i & 1: m &= NB[i]\n    return m\npc = lambda m: bin(m).count(\'1\')\nlog(\'neighbourhood sizes\', sorted({pc(x) for x in NB}))\n# closed sets with |A| >= 13: intersections of neighbourhoods, DFS over generators in increasing order\nTH = 13\nclosed = {}\ndef dfs(start, S):\n    for b in range(start, N):\n        S2 = S & NB[b]\n        if pc(S2) < TH or S2 == S: continue\n        if S2 in closed: continue\n        Bc = C(S2); closed[S2] = Bc\n        dfs(b + 1, S2)\ndfs(0, ALL)\nlog(\'closed A-sets with |A| >= %d:\' % TH, len(closed))\nfrom collections import Counter\nhist = Counter((pc(A), pc(B)) for A, B in closed.items())\nfor k in sorted(hist): log(\'  |A|, |B| =\', k, \'count\', hist[k])\nlog(\'max |B| over closed A with |A| >= 13:\', max(pc(B) for B in closed.values()))\njson.dump([[A, B] for A, B in closed.items()], open(\'bicliques.json\', \'w\'))\nlog(\'DONE\')\n'}
for k, v in FILES.items(): open(k, 'w').write(v)
rc = 0
for s in ['bicliques.py', 'spanlemma.py']:
    p = subprocess.Popen([sys.executable, '-u', s], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    log = open(s.replace('.py', '.log'), 'w')
    for line in p.stdout: print(line, end='', flush=True); log.write(line); log.flush()
    r = p.wait(); print('EXIT', s, r, flush=True); rc = rc or r
if rc: raise SystemExit(rc)
